    ULONGLONG mle_hdr_base;
    ULONGLONG vtd_pmr_lo_base;
    ULONGLONG vtd_pmr_lo_size;
    ULONGLONG vtd_pmr_hi_base;
    ULONGLONG vtd_pmr_hi_size;
