constexpr ULONG VGK_GHCB_INFO_SNP_RUN_VMPL_RESP            = 0x017u;
constexpr ULONG VGK_GHCB_INFO_HYP_FEATURE_REQ              = 0x080u;
constexpr ULONG VGK_GHCB_INFO_HYP_FEATURE_RESP             = 0x081u;
